-- 0022: Weekly ACL & Achilles update (2026-11-24). Generated by scripts/weekly/build-migration.mjs.
--   Weekly run 2026-11-24 (since 2026-11-17). NFL: no new confirmed 2026-season full ACL/Achilles tears this week.
--   NFL 2025-season carryovers added (owner-approved candidates, season = 2025, not counted in 2026 totals):
--     Tyrell Shavers (BUF WR) torn ACL in the Jan 11, 2026 Wild Card win at Jacksonville (Bills.com, Jan 13); practice window Oct 28; activated Nov 18; season debut Nov 22 vs MIA -> returned.
--     Omarr Norman-Lott (KC DT) torn right ACL Oct 19, 2025, Week 7 vs LV at Arrowhead (ESPN); practice window Oct 28, 2026; activated Nov 18; inactive Nov 22 -> still practice_limited.
--   Micah Parsons unchanged (game_ready; debut Nov 25 vs LAR not yet played).
--   NBA: no new confirmed tears. Thomas Sorber had a third right-knee procedure (arthroscopic, patellofemoral inflammation) on Nov 17; back on court in 6-8 weeks.
--   Watching (not in DB): Cole Kmet (CHI, knee; ACL still unconfirmed), Kentavius Street (CHI, knee; out for season, no diagnosis released), Harold Landry III (NE, PUP; injury undisclosed), Brandon Ingram (LAC, partial Achilles; not counted).
--   Surfaces: Shavers and Norman-Lott are in-game tears, so surface comes from the stadium record (natural grass). Side for Shavers not reported; mechanisms left blank.
-- League-qualified lookups; every statement is guarded, so re-running is a no-op.
SET NAMES utf8mb4;

-- Tyrell Shavers (NFL BUF)
INSERT INTO players (league, first_name, last_name, slug, position, team_id)
SELECT 'NFL', 'Tyrell', 'Shavers', 'tyrell-shavers', 'WR', (SELECT id FROM teams WHERE league = 'NFL' AND abbreviation = 'BUF')
WHERE NOT EXISTS (SELECT 1 FROM players WHERE slug = 'tyrell-shavers');
UPDATE players SET dob = COALESCE(dob, '1999-08-18'), height_in = COALESCE(height_in, 76), weight_lb = COALESCE(weight_lb, 211), headshot_path = COALESCE(headshot_path, '/players/tyrell-shavers.png'), team_id = COALESCE((SELECT id FROM teams WHERE league = 'NFL' AND abbreviation = 'BUF'), team_id) WHERE slug = 'tyrell-shavers' AND league = 'NFL';

