-- Tear: tyrell-shavers ACL 2026-01-11
INSERT INTO injuries (player_id, injury_type, injury_date, season, week, stadium_id, home_away, opponent_id, mechanism, body_side, phase, severity_notes, source)
SELECT p.id, 'ACL', '2026-01-11', 2025,
       NULL, (SELECT id FROM stadiums WHERE league = 'NFL' AND slug = 'everbank-stadium'), 'away', (SELECT id FROM teams WHERE league = 'NFL' AND abbreviation = 'JAX'), NULL, NULL, 'playoffs',
       'Hurt during the Bills'' AFC Wild Card win at Jacksonville on Jan. 11, 2026, but came back in and finished the game, catching one pass for 14 yards and playing more than half of the team''s snaps. Further tests revealed a torn ACL, ending his postseason, head coach Sean McDermott announced on Jan. 13.',
       'https://www.buffalobills.com/news/bills-announce-wr-tyrell-shavers-tore-his-acl-vs-jaguars'
FROM players p WHERE p.slug = 'tyrell-shavers' AND p.league = 'NFL'
  AND NOT EXISTS (SELECT 1 FROM injuries i WHERE i.player_id = p.id AND i.injury_type = 'ACL' AND i.injury_date = '2026-01-11');

