FROM injuries i JOIN players p ON p.id = i.player_id
WHERE p.slug = 'tyrell-shavers' AND p.league = 'NFL' AND i.injury_type = 'ACL' AND i.injury_date = '2026-01-11'
  AND NOT EXISTS (SELECT 1 FROM progress_updates x WHERE x.injury_id = i.id AND x.stage = 'diagnosis' AND x.update_date = '2026-01-13');

